/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 > /tmp/r001_runtime.json
python3 - <<'PY'
import json
r=json.load(open('/tmp/r001_runtime.json'))
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k,json.dumps(v))
c=r['context']; print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge']: print(k,json.dumps(v))
print('HISTORY SUMMARY')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k not in ['validation','config','study','proposal','source','code']},default=str)[:3000])
 print('config',h.get('config'), 'score',h.get('validation',{}).get('macro_auc'))
PY"

