import ast,copy,hashlib,json,pathlib,math
root=pathlib.Path('/workspace');r=json.load(open('/tmp/r001_runtime.json'));p=json.load(open(root/'proposal.json'))
def schema_check(x,s,path='"'$'"'):
 t=s.get('type'); types={'object':dict,'array':list,'string':str,'boolean':bool}
 if t: assert isinstance(x,types[t]),(path,t,type(x))
 if 'const' in s:assert x==s['const'],path
 if 'enum' in s:assert x in s['enum'],path
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'required')
  if s.get('additionalProperties') is False:assert set(x)<=set(s['properties']),(path,'extra')
  for k,v in x.items():
   if k in s.get('properties',{}):schema_check(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x):schema_check(v,s.get('items',{}),path+f'[{i}]')
 if isinstance(x,str):assert len(x)>=s.get('minLength',0),path
schema_check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
old=ast.parse((root/'history_g3_r0010_content_plus_linear_private.py').read_text())
old_model=next(n for n in old.body if isinstance(n,ast.ClassDef) and n.name=='Model')
old_methods={n.name:n for n in old_model.body if isinstance(n,ast.FunctionDef)}
expected_cells={('private','mean','linear'),('mean','private','linear'),('private','mean','copy'),('mean','private','copy')}
cells=set();normalized=[];hashes={}
for v in p['variants']:
 assert pathlib.Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 text=(root/v['file']).read_text();compile(text,v['file'],'exec');tree=ast.parse(text)
 cfg_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets));config=ast.literal_eval(cfg_node.value)
 assert config==v['config'];cells.add((config['task_routing'],config['task_extra_routing'],config['task_extra_basis']))
 hashes[v['file']]=hashlib.sha256(text.encode()).hexdigest();assert hashes[v['file']] in v['note']
 model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model');methods={n.name:n for n in model.body if isinstance(n,ast.FunctionDef)}
 init=methods['__init__']; defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,val in config.items():assert ast.literal_eval(defaults[k])==val,(v['file'],k)
 for name,method in old_methods.items():
  if name not in ['__init__','_task_pool']:assert ast.dump(method)==ast.dump(methods[name]),(v['file'],name)
 # Initialization has only a route value check and a non-parameter attribute assignment added.
 body=[]
 for n in init.body:
  if isinstance(n,ast.If) and 'task_extra_routing' in ast.unparse(n.test):continue
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Attribute) and t.attr=='task_extra_routing' for t in n.targets):continue
  body.append(n)
 assert ast.dump(ast.Module(body=body,type_ignores=[]))==ast.dump(ast.Module(body=old_methods['__init__'].body,type_ignores=[])),v['file']
 # All non-Model definitions (including JointBlock) and imports unchanged, except doc/CONFIG.
 def fixed_nodes(t):return [n for n in t.body if not (isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str)) and not (isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets)) and not (isinstance(n,ast.ClassDef) and n.name=='Model')]
 assert ast.dump(ast.Module(body=fixed_nodes(tree),type_ignores=[]))==ast.dump(ast.Module(body=fixed_nodes(old),type_ignores=[]))
 for n in ast.walk(tree):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[n.module] if isinstance(n,ast.ImportFrom) else [a.name for a in n.names]
   assert all(name.split('.')[0] in ['math','torch','unirank'] for name in names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in ['open','exec','eval','compile','__import__','getattr','setattr']
 norm=copy.deepcopy(tree)
 for n in norm.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):n.value=ast.Constant(None)
  if isinstance(n,ast.ClassDef) and n.name=='Model':
   f=next(x for x in n.body if isinstance(x,ast.FunctionDef) and x.name=='__init__')
   f.args.defaults=[ast.Constant(None) for _ in f.args.defaults]
 normalized.append(ast.dump(norm))
assert cells==expected_cells
assert len(set(normalized))==1
# Count the full factorial, including the four prior diagonal cells, without treating them as repetitions.
all_cells=set(cells)
for h in r['context']['history']:
 if h['id'].startswith('g3-r0010-'):
  cfg=h['config'];all_cells.add((cfg['task_routing'],cfg['task_routing'],cfg['task_extra_basis']))
assert len(all_cells)==8
# Independent scalar reference for the planned route factorization, not torch execution.
cases=0
for n in [0,1,2,3,16,64,100]:
 vals=[(i%7-3)/4 for i in range(n)]
 raw=[[(i+1)*(t-1.2)/31+math.sin(i+t) for t in range(4)] for i in range(n)]
 mean=[sum(row)/4 for row in raw]
 centered=[2*i-n+1 for i in range(n)]
 rms=math.sqrt(sum(z*z for z in centered)/max(n,1))
 linear=[z/max(rms,1e-6) for z in centered]
 for basis_name,basis in [('linear',linear),('copy',[1.]*n)]:
  def pool(route,b):return [sum((raw[i][t] if route=='private' else mean[i])*b[i]*vals[i] for i in range(n)) for t in range(4)]
  for cr in ['private','mean']:
   for er in ['private','mean']:
    content=pool(cr,[1.]*n);extra=pool(er,basis)
    combined=[a+0.37*b for a,b in zip(content,extra)]
    assert all(math.isfinite(z) for z in combined)
    if cr==er:
     old_formula=[sum((raw[i][t] if cr=='private' else mean[i])*vals[i]*(1+0.37*basis[i]) for i in range(n)) for t in range(4)]
     assert all(math.isclose(a,b,rel_tol=1e-10,abs_tol=1e-10) for a,b in zip(combined,old_formula))
    if er=='mean':assert max(extra)-min(extra)<1e-10
    if n<=1 and basis_name=='linear':assert all(z==0 for z in extra)
    if cr=='mean':assert max(content)-min(content)<1e-10
    # With P=0, varying E route or basis cannot change the content function.
